import{_ as a,o as t,c as o,a3 as d}from"./chunks/framework.DMtjdCb-.js";const i="/help/assets/offline-update.BHLXGYlI.png",k=JSON.parse('{"title":"9. 更新与备份","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/updates.md","filePath":"zh-Hans/updates.md"}'),c={name:"zh-Hans/updates.md"};function n(r,e,l,s,h,p){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="_9-更新与备份" tabindex="-1">9. 更新与备份 <a class="header-anchor" href="#_9-更新与备份" aria-label="Permalink to &quot;9. 更新与备份&quot;">​</a></h1><p>更新 AnimeMachine 程序会保留原有设置、作品资料与观看记录。Bangumi Archive 是作品资料底包，与程序版本分别更新。</p><h2 id="在线更新" tabindex="-1">在线更新 <a class="header-anchor" href="#在线更新" aria-label="Permalink to &quot;在线更新&quot;">​</a></h2><ol><li>打开 <strong>设置 → 检查更新</strong>。</li><li>点击检查，查看新版本与更新说明。</li><li>根据页面可用的升级操作确认安装，等待程序重启并刷新页面。</li><li>核对页面版本号。Docker 中使用镜像重新部署也可以完成更新。</li></ol><h2 id="上传离线升级包" tabindex="-1">上传离线升级包 <a class="header-anchor" href="#上传离线升级包" aria-label="Permalink to &quot;上传离线升级包&quot;">​</a></h2><p>0.5.1 起可在同一页面上传离线升级包：</p><ol><li>在可以下载文件的设备上取得匹配当前部署方式的 <code>.anm-update.zip</code>。</li><li>在 <strong>设置 → 检查更新</strong> 选择文件并上传。</li><li>等待校验、安装与重启，刷新后核对版本。</li></ol><p><img src="'+i+'" alt="离线升级入口：选择与当前部署方式匹配的包" loading="lazy"></p><table tabindex="0"><thead><tr><th>当前部署</th><th>使用的升级包</th></tr></thead><tbody><tr><td>Windows 发布包</td><td><code>AnimeMachine-版本-windows.anm-update.zip</code></td></tr><tr><td>Docker</td><td><code>AnimeMachine-版本-docker.anm-update.zip</code></td></tr></tbody></table><p>普通 <code>release-windows.zip</code> 用于完整解压安装，Docker 的 <code>tar.gz</code> 是离线镜像；它们与上传入口使用的升级包用途不同。文件不匹配或校验失败时，当前可用版本继续运行。</p><h2 id="docker-0-5-0-离线升级" tabindex="-1">Docker 0.5.0 离线升级 <a class="header-anchor" href="#docker-0-5-0-离线升级" aria-label="Permalink to &quot;Docker 0.5.0 离线升级&quot;">​</a></h2><p>正式发布的离线镜像可在 <a href="https://github.com/kyupi-git/animemachine/releases/latest" target="_blank" rel="noreferrer">Releases</a> 下载，文件名中的 <code>amd64</code> 对应 Intel / AMD，<code>arm64</code> 对应 ARM。</p><p>0.5.0 还没有上传入口，可先从本地镜像升级：</p><ol><li>把 <code>AnimeMachine-0.5.2-docker-linux-amd64.tar.gz</code> 上传到 NAS。该文件用于 Intel / AMD；ARM 设备选择对应架构的镜像。</li><li>在终端导入镜像：</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AnimeMachine-0.5.2-docker-linux-amd64.tar.gz</span></span></code></pre></div><ol start="3"><li>在项目目录的 <code>.env</code> 中设置 <code>ANM_IMAGE=animemachine:0.5.2</code>；使用默认完整组合时，同样设置 <code>TORRENT_COLLECTOR_IMAGE=animemachine:0.5.2</code>。</li><li>在该目录运行 <code>docker compose up -d --pull never</code>，刷新并核对版本。</li></ol><p>自定义 Compose 若直接写了镜像地址，则修改相应服务的 <code>image</code> 值。目录挂载、环境配置和数据目录继续使用原值。</p><h2 id="电脑上手动替换发布包" tabindex="-1">电脑上手动替换发布包 <a class="header-anchor" href="#电脑上手动替换发布包" aria-label="Permalink to &quot;电脑上手动替换发布包&quot;">​</a></h2><p>停止旧程序，将新版解压到新目录，再把旧目录中的 <code>config.json</code>、<code>.env.local</code>（如有）和整个 <code>data</code> 目录复制到新目录，启动新版。媒体放在独立目录时，保持原路径可访问。</p><h2 id="下载与恢复备份" tabindex="-1">下载与恢复备份 <a class="header-anchor" href="#下载与恢复备份" aria-label="Permalink to &quot;下载与恢复备份&quot;">​</a></h2><p>在 <strong>设置 → 用户 → 备份与恢复</strong> 点击 <strong>下载备份</strong>，保存生成的 ZIP。备份包含设置、账号、资源跟踪和观看记录，不包含媒体文件与作品底库。</p><p>恢复时点击 <strong>恢复备份</strong>，选择 ZIP，核对备份版本与记录数量，再点击 <strong>恢复并重启</strong>。重启后使用备份中的账号登录，并核对连接地址和媒体目录。部署时通过环境变量指定的设置仍以部署配置为准。</p><p>备份包含账号及连接信息，请保存在自己的设备中。迁移整套作品库或保留手动媒体识别结果时，仍需备份下列完整数据目录。</p><h2 id="备份需要保留什么" tabindex="-1">备份需要保留什么 <a class="header-anchor" href="#备份需要保留什么" aria-label="Permalink to &quot;备份需要保留什么&quot;">​</a></h2><p>停止 AnimeMachine 后备份设置与 <code>data</code>，媒体按自己的备份方式保存。</p><table tabindex="0"><thead><tr><th>部署方式</th><th>备份内容</th></tr></thead><tbody><tr><td>电脑</td><td><code>config.json</code>、<code>.env.local</code>（如有）、<code>data</code></td></tr><tr><td>Docker</td><td><code>compose.yaml</code>、<code>.env</code>（如有）、<code>config</code>、<code>data</code>，以及自定义的挂载配置</td></tr></tbody></table><p>恢复时使用同一套目录映射和账户数据。目录中的 <code>initial-admin.txt</code>、服务密码文件属于账户信息，随备份妥善保存。</p>',27)])])}const u=a(c,[["render",n]]);export{k as __pageData,u as default};
